def is_valid(edges, n=14):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    degrees = [len(adj[i]) for i in range(n)]
    if any(d < 5 or d > 7 for d in degrees):
        return False

    # Chromatic number check (simple greedy coloring)
    # For small graphs, we can try to color it
    def get_chromatic_number(adj, n):
        # Try coloring with k colors
        for k in range(1, 7):
            coloring = [-1] * n
            def can_color(u):
                if u == n:
                    return True
                for c in range(k):
                    if all(coloring[v] != c for v in adj[u]):
                        coloring[u] = c
                        if can_color(u + 1):
                            return True
                        coloring[u] = -1
                return False
            if can_color(0):
                return k
        return 7

    chi = get_chromatic_number(adj, n)
    if not (3 <= chi <= 5):
        return False

    return True

