# Let's try a random construction.
def generate_random_5_regular(n=14):
    while True:
        edges = set()
        adj = [set() for _ in range(n)]
        for i in range(n):
            while len(adj[i]) < 5:
                target = random.randint(0, n - 1)
                if target != i and target not in adj[i]:
                    edges.add(tuple(sorted((i, target))))
                    adj[i].add(target)
                    adj[target].add(i)

        # Check if all degrees are 5
        if all(len(adj[i]) == 5 for i in range(n)):
            return list(edges)

